// Compares the Kotlin port of the ladder's scoring against numbers generated by the
// engine itself (`npm run golden` in engine/). This is the test that makes the phone's
// autonomy safe: if the two disagree, this fails at build time instead of the user
// silently getting a worse transport than the server would have chosen.
package ir.savak.client.engine

import com.google.common.truth.Truth.assertThat
import org.json.JSONObject
import org.junit.Test

class LadderParityTest {

    private val doc by lazy {
        val text = javaClass.getResourceAsStream("/parity/golden.json")!!.bufferedReader().use { it.readText() }
        JSONObject(text)
    }
    private val tolerance get() = doc.optDouble("tolerance", 1e-5)

    @Test
    fun `every scenario's ranking matches the engine row for row`() {
        val scenarios = doc.getJSONArray("scenarios")
        assertThat(scenarios.length()).isAtLeast(8)
        for (i in 0 until scenarios.length()) {
            val sc = scenarios.getJSONObject(i)
            val name = sc.getString("name")
            val link = snapshotOf(sc.getJSONObject("link"))
            val expected = sc.getJSONArray("expected")
            val samples = sc.optJSONObject("samples")?.let { so ->
                so.keys().asSequence().associateWith { k ->
                    val v = so.getJSONObject(k)
                    Sample(v.optInt("attempts"), v.optInt("failures"), v.optDouble("downMbps").orNull(), v.optDouble("rttMs").orNull(), v.optDouble("jitterMs").orNull())
                }
            } ?: emptyMap()
            val inputs = HashMap<String, ScoringInputs>()
            val hop = HashMap<String, Int>()
            for (j in 0 until expected.length()) {
                val row = expected.getJSONObject(j)
                val inp = row.getJSONObject("inputs")
                inputs[row.getString("rungId")] = ScoringInputs(
                    evasionApplied = inp.optDouble("evasionApplied", 0.0),
                    canHop = inp.optBoolean("canHop"),
                    naiveQuic = if (inp.has("naiveQuic")) inp.getBoolean("naiveQuic") else null,
                )
                hop[row.getString("rungId")] = if (inp.optBoolean("canHop")) 4 else 0
            }
            val scoring = LadderScore(
                snapshot = link,
                nodeProtocols = LadderTable.ALL.map { it.id }.toSet(),
                mode = sc.getString("mode"),
                pathMtu = sc.getJSONObject("requested").optInt("mtu", 1420),
                tunings = inputs.mapValues { (_, v) -> Tuning(canHop = v.canHop, naiveQuic = v.naiveQuic) },
                hopRanges = hop,
                evasionApplied = inputs.mapValues { it.value.evasionApplied },
            )
            val got = scoring.rank(samples)
            // The device must consider exactly the rungs the engine considered, in the same
            // order — a re-ranked list is how "it worked yesterday" bugs start.
            assertThat(got.map { it.spec.id }).containsExactlyElementsIn(
                (0 until expected.length()).map { expected.getJSONObject(it).getString("rungId") },
            ).inOrder()

            for (j in 0 until expected.length()) {
                val want = expected.getJSONObject(j)
                val row = got.first { it.spec.id == want.getString("rungId") }
                val ctx = "$name / ${row.spec.id}"
                assertThat(row.feasible).named("$ctx feasible").isEqualTo(want.getBoolean("feasible"))
                if (want.getString("reason").isNotEmpty()) {
                    assertThat(row.reason).named("$ctx reason").contains(want.getString("reason").take(24))
                }
                assertThat(row.score).named("$ctx score").isWithin(tolerance).of(want.getDouble("score"))
                val parts = want.getJSONObject("parts")
                assertThat(row.parts.throughput).named("$ctx throughput").isWithin(tolerance).of(parts.getDouble("throughput"))
                assertThat(row.parts.latency).named("$ctx latency").isWithin(tolerance).of(parts.getDouble("latency"))
                assertThat(row.parts.stability).named("$ctx stability").isWithin(tolerance).of(parts.getDouble("stability"))
                assertThat(row.parts.evasion).named("$ctx evasion").isWithin(tolerance).of(parts.getDouble("evasion"))
                assertThat(row.parts.cost).named("$ctx cost").isWithin(tolerance).of(parts.getDouble("cost"))
            }
        }
    }

    @Test
    fun `the generated table is consistent with itself`() {
        assertThat(LadderTable.ALL.size).isAtLeast(9)
        assertThat(LadderTable.BY_ID.keys).containsExactlyElementsIn(LadderTable.ALL.map { it.id }).inOrder()
        for ((mode, w) in LadderTable.WEIGHTS) {
            val sum = w.sum()
            assertThat("$mode weights should total 1").isWithin(0.001).of(sum)
        }
        // Real facts that must never be lost in regeneration.
        assertThat(LadderTable.BY_ID.getValue("vless_reality_tcp").affinity.dpiSni).isGreaterThan(0.9)
        assertThat(LadderTable.BY_ID.getValue("wg_uot").carrier).isEqualTo("endpoint")
        assertThat(LadderTable.BY_ID.getValue("hy2_brutal").requiresQuic).isTrue()
        assertThat(LadderTable.BY_ID.getValue("ss2022").requiresUdp).isFalse()
    }

    @Test
    fun `hysteresis never switches for a marginal win`() {
        val sel = Selector(minSwitchGainPct = 15.0, dwellMs = 0, now = { 0L })
        val a = Ranked(LadderTable.BY_ID.getValue("vless_reality_tcp"), inLadder = true, feasible = true, reason = "", score = 0.50, parts = parts(0.5))
        val b = Ranked(LadderTable.BY_ID.getValue("hy2_brutal"), inLadder = true, feasible = true, reason = "", score = 0.52, parts = parts(0.52))
        val ranked = listOf(b, a)
        assertThat(sel.decide(ranked).pick).isEqualTo("hy2_brutal")
        // Now the incumbent leads slightly: 4% is not worth a handshake.
        val ranked2 = listOf(a.copy(score = 0.54), b.copy(score = 0.52))
        val d = sel.decide(ranked2)
        assertThat(d.switched).isFalse()
        assertThat(d.pick).isEqualTo("hy2_brutal")
        assertThat(d.why).contains("within")
    }

    private fun parts(v: Double) = Parts(v, v, v, v, v, v * 100)

    private fun Double.orNull() = if (isNaN()) null else this

    private fun snapshotOf(o: JSONObject) = LinkSnapshot(
        access = if (o.optString("access") == "cellular") Access.CELLULAR else Access.WIFI,
        rttMs = o.optDoubleOrNull("rttMs"),
        jitterMs = o.optDoubleOrNull("jitterMs"),
        lossPct = o.optDoubleOrNull("lossPct"),
        downMbps = o.optDoubleOrNull("downMbps"),
        upMbps = o.optDoubleOrNull("upMbps"),
        mtuCap = if (o.has("mtuCap")) o.getInt("mtuCap") else null,
        udpBlocked = o.optBoolOrNull("udpBlocked"),
        quicBlocked = o.optBoolOrNull("quicBlocked"),
        sniFiltered = o.optBoolOrNull("sniFiltered"),
        portThrottled = o.optBoolOrNull("portThrottled"),
        udpThrottled = o.optBoolOrNull("udpThrottled"),
        portBlocked = o.optBoolOrNull("portBlocked"),
        quicFingerprinted = o.optBoolOrNull("quicFingerprinted"),
        bandwidthShaped = o.optBoolOrNull("bandwidthShaped"),
        sizeHeuristic = o.optBoolOrNull("sizeHeuristic"),
        activeProbeSuspected = o.optBoolOrNull("activeProbeSuspected"),
        ipRangeBlocked = o.optBoolOrNull("ipRangeBlocked"),
        bothRadios = o.optBoolean("bothRadios", false),
        source = o.optString("source", "fixture"),
    )

    private fun JSONObject.optDoubleOrNull(key: String): Double? = if (has(key) && !isNull(key)) getDouble(key) else null

    private fun JSONObject.optBoolOrNull(key: String): Boolean? = if (has(key) && !isNull(key)) getBoolean(key) else null
}
